  "code": "def isEmpty(s): return len(s) == 0\ndef dequeue(q): return q.pop(0)\ndef push(s, x): s.append(x)\ndef pop(s): return s.pop()\nqueue = [\"A\", \"B\", \"C\"]\ncount = 0\nwhile not isEmpty(queue):\n    dequeue(queue)\n    count = count + 1\nprint(count)                    # 3\nscores = [10, 20, 24]\ntotal = 0\nwhile not isEmpty(scores):\n    total = total + pop(scores)\nprint(total)                    # 54",
