  "code": "def halvings(n):            # O(log n)\n    steps = 0\n    while n > 1:\n        n = n // 2\n        steps = steps + 1\n    return steps\nprint(halvings(16), halvings(1000), halvings(1000000))\ndef try_every_combination(n):   # O(2^n)\n    steps = 0\n    for combo in range(2 ** n):\n        steps = steps + 1\n    return steps\nprint(try_every_combination(3), try_every_combination(10), try_every_combination(20))",
